// Headline figures for site copy. datasetFacts.json is generated by
// scripts/build_dataset.py, so these numbers always match the published data.
import facts from "./datasetFacts.json";

const fmt = (n) => Number(n).toLocaleString("en-NG");

export const FACTS = {
  ...facts,
  recordsLabel: fmt(facts.records),
  yearsLabel: `${facts.firstTableYear}–${facts.lastTableYear}`,
  placesLabel: `${facts.states} states${facts.includesFct ? " and the FCT" : ""}`,
};

export const OPERATORS = "UpNawt Studio and Synergia Systems Ltd";

export const SOURCE_NAME = "EFCC Narrative of Convictions";
